using System;
using System.Linq;
using UnityEngine;
public static class LatestFeedbackTests {
 public static void RunFinal(){RoadFatigueFinalVerification.Run();SouthRoute();FacilityRoutes();FuelDeparture();ExitContinuity();Debug.Log("LATEST_FEEDBACK_FINAL_EDITOR_OK");}
 public static void ExitContinuity(){MapCatalog.LockedRegion="eungye";var map=MapCatalog.Load();FuelStationLayout.Apply(map);var root=new GameObject("continuous authored exit");try{var nav=root.AddComponent<RoadNavigation>();nav.Build(map,root.transform);var stations=FuelStationLayout.For(map);foreach(var s in stations)CheckExit(nav,root.transform,s.drivePath,stations.First(x=>x.id!=s.id).approach,s.id);var rest=FuelStationLayout.Rest(map);Check(rest!=null,"rest departure fixture");CheckExit(nav,root.transform,rest.drivePath,stations[0].approach,"rest");var restaurant=RestaurantSiteLayout.For(map);CheckExit(nav,root.transform,restaurant.leave,stations[0].approach,"restaurant");root.transform.position=new Vector3(-100,0,-100);Check(nav.PreviewTo(stations[0].approach).Count==0,"offsite remains rejected");}finally{UnityEngine.Object.DestroyImmediate(root);}Debug.Log("LATEST_EXIT_CONTINUITY_OK");}
 static void CheckExit(RoadNavigation nav,Transform taxi,Vector3[] path,MapStop target,string name){for(int i=path.Length/2;i<path.Length;i++){var dir=path[Math.Min(i+1,path.Length-1)]-path[Math.Max(0,i-1)];taxi.SetPositionAndRotation(path[i],Quaternion.LookRotation(dir));Check(nav.PreviewTo(target).Count>1,"continuous "+name+" exit sample "+i);nav.SetDestination(target);Check(nav.path.Count>1,"active "+name+" exit sample "+i);}}
 public static void InspectSouth(){var p=ProjectMapStore.Load(ProjectMapBuild.Root);var map=p.Compose();var g=new HdRoadGraph(map);var src=RoadMapAuthoringOperations.LineageSegment(p.document,"local:7847:9404:8047:6565:part:2",160);int a=Array.FindIndex(g.edges,e=>e.id==src.id);var stop=map.stops.First(s=>s.name.Contains("국도42")&&s.name.EndsWith("1"));foreach(string id in new[]{"join:local:7918:6167:7847:3996:1","join:local:7737:9374:7933:6566:1"}){int via=Array.FindIndex(g.edges,e=>e.id==id);var to=g.Route(a,160-src.sourceOffset,via,0);var rest=g.Route(via,0,stop.laneEdge,stop.laneAt);Debug.Log("INSPECT_SOUTH "+id+" to="+(to==null?"NULL":to.path.length.ToString())+" rest="+(rest==null?"NULL":rest.path.length.ToString()));}foreach(var e in g.edges.Where(e=>e.id.StartsWith("reviewed:latest:south-change:")))Debug.Log("INSPECT_CHANGE "+e.id+" disabled="+e.disabled+" next="+string.Join(",",e.next.Select(i=>g.edges[i].id)));FuelDeparture();}
 public static void ApplySouth(){string root=ProjectMapBuild.Root,token=ProjectMapStore.Fingerprint(root);var p=ProjectMapStore.Load(root);var d=PlaytestLaneChangeRepair.ApplySouthbound(p);var revised=ProjectMapPackage.Create(p.baseline,d);SouthRoute(revised);ProjectMapStore.Save(root,revised,token);ProjectMapBuild.Prepare();PlaytestDirectTurnTests.Run();RoadFollowupTests.Run();}
 public static void FuelDeparture(){MapCatalog.LockedRegion="eungye";var map=MapCatalog.Load();FuelStationLayout.Apply(map);var root=new GameObject("fuel departure");try{var n=root.AddComponent<RoadNavigation>();n.Build(map,root.transform);var stations=FuelStationLayout.For(map);foreach(var site in stations){root.transform.SetPositionAndRotation(site.pump,Quaternion.LookRotation(site.direction));var target=stations.First(s=>s.id!=site.id);var path=n.PreviewTo(target.approach);Check(path.Count>1,"facility departure preview "+site.id);n.SetDestination(target.approach);Check(n.path.Count>1,"facility departure active guidance "+site.id);Check(Vector3.Distance(n.path[0],site.pump)<1,"guidance begins at real pump, not snapped road");}root.transform.position=new Vector3(-100,0,-100);Check(n.PreviewTo(stations[0].approach).Count==0,"outside authored facility no fabricated approach");}finally{UnityEngine.Object.DestroyImmediate(root);}Debug.Log("LATEST_FUEL_DEPARTURE_OK");}
 static void Check(bool ok,string message){if(!ok)throw new Exception("LATEST_FEEDBACK_FAIL "+message);Debug.Log("LATEST_PASS "+message);}
 public static void FacilityRoutes(){
  MapCatalog.LockedRegion="eungye";var root=new GameObject("latest real parking facility routes");try{
   var s=root.AddComponent<DriveSession>();s.world=root.AddComponent<WorldBuilder>();s.world.map=MapCatalog.Load();FuelStationLayout.Apply(s.world.map);s.jobs=root.AddComponent<PassengerJobs>();s.jobs.session=s;s.jobs.stops=s.world.map.stops;s.jobs.nav=root.AddComponent<RoadNavigation>();s.jobs.nav.Build(s.world.map,root.transform);s.services=root.AddComponent<ServiceStops>();s.services.session=s;s.taxi=root.AddComponent<TaxiController>();s.taxi.body=root.AddComponent<Rigidbody>();s.taxi.body.isKinematic=true;s.business=root.AddComponent<BusinessProgress>();s.business.ledger=new EconomyLedger(PrototypeSettings.ForThreeDays());var parking=s.services.ParkingStop;root.transform.SetPositionAndRotation(parking.Kerb,Quaternion.LookRotation(parking.Direction));foreach(var p in s.services.Stations)Check(s.jobs.nav.PreviewTo(p.approach).Count>1,"parking routes to "+p.name);
  }finally{UnityEngine.Object.DestroyImmediate(root);Time.timeScale=1;}Debug.Log("LATEST_FACILITY_ROUTES_OK");
 }
 public static void SouthRoute(){SouthRoute(ProjectMapStore.Load(ProjectMapBuild.Root));}
 static void SouthRoute(ProjectMapPackage p){var map=p.Compose();var g=new HdRoadGraph(map);var source=RoadMapAuthoringOperations.LineageSegment(p.document,"local:7847:9404:8047:6565:part:2",160);int start=Array.FindIndex(g.edges,e=>e.id==source.id);var goal=map.stops.First(s=>s.name.Contains("국도42")&&s.name.EndsWith("1"));var r=g.Route(start,160-source.sourceOffset,goal.laneEdge,goal.laneAt);Check(r!=null,"southbound west drop reachable");Debug.Log("LATEST_SOUTH distance="+r.path.length+" "+string.Join(" | ",r.edges.Select(i=>g.edges[i].id)));Check(!r.edges.Any(i=>g.paths[i].points.Any(q=>q.z<330)),"southbound west drop avoids southern block U-loop");Check(r.path.length<1300,"southbound west drop stays under1300m");Debug.Log("LATEST_SOUTH_ROUTE_OK");}
 public static void Diagnose(){
  MapCatalog.LockedRegion="eungye";var map=MapCatalog.Load();FuelStationLayout.Apply(map);var graph=new HdRoadGraph(map);
  foreach(var stop in map.stops)Debug.Log("LATEST_STOP "+stop.name+" "+stop.V()+" edge="+(stop.graphStop?graph.edges[stop.laneEdge].id:"NO_GRAPH")+" at="+stop.laneAt);
  foreach(var s in FuelStationLayout.For(map))Debug.Log("LATEST_STATION "+s.id+" edge="+graph.edges[s.approach.laneEdge].id+" at="+s.approach.laneAt);
  foreach(var o in map.projectScene.objects.Where(o=>o.IsService))Debug.Log("LATEST_SERVICE "+o.name+" pos="+o.Position+" lane="+o.laneId+" at="+o.laneAt);
  var root=new GameObject("route diagnostics");try{var nav=root.AddComponent<RoadNavigation>();nav.Build(map,root.transform);
   foreach(string id in new[]{"local:7737:9374:7933:6566","local:7792:9389:7990:6566","local:7847:9404:8047:6565","local:5978:17124:10508:15987"}){int edge=Array.FindIndex(graph.edges,e=>e.id==id);if(edge<0)continue;float at=Math.Min(200,graph.paths[edge].length-20);root.transform.SetPositionAndRotation(graph.paths[edge].Position(at),Quaternion.LookRotation(graph.paths[edge].Tangent(at)));Debug.Log("LATEST_START edge="+id+" at="+at);foreach(var s in FuelStationLayout.For(map)){var r=graph.Route(edge,at,s.approach.laneEdge,s.approach.laneAt);Debug.Log("LATEST_FUEL_ROUTE "+s.id+" "+(r==null?"NULL":"dist="+r.path.length));}var target=map.stops.FirstOrDefault(s=>s.name.Contains("국도42")&&s.name.EndsWith("1"));if(target!=null){var r=graph.Route(edge,at,target.laneEdge,target.laneAt);Debug.Log("LATEST_WEST_ROUTE "+(r==null?"NULL":"distance="+r.path.length+" "+string.Join(" | ",r.edges.Select(i=>graph.edges[i].id))));}}
  }finally{UnityEngine.Object.DestroyImmediate(root);}Debug.Log("LATEST_DIAGNOSE_OK");
 }
}
